{"cmd":"python3 - <<'PY'
import json
from docx import Document

DATA_PATH='/root/employee_data.json'
TEMPLATE_PATH='/root/offer_letter_template.docx'
OUT_PATH='/root/offer_letter_filled.docx'

with open(DATA_PATH,'r') as f:
    data=json.load(f)

# Build placeholder mapping
mapping={f'{{{{{k}}}}}':str(v) for k,v in data.items()}

# Conditional handling
relocation_yes = str(data.get('RELOCATION_PACKAGE','')).strip().lower() == 'yes'


doc=Document(TEMPLATE_PATH)

from docx.text.paragraph import Paragraph

def remove_paragraph(p: Paragraph):
    p._element.getparent().remove(p._element)
    p._p = p._element = None


def process_paragraph(p: Paragraph):
    text = p.text
    if '{{IF_RELOCATION}}' in text or '{{END_IF_RELOCATION}}' in text:
        if '{{IF_RELOCATION}}' in text and '{{END_IF_RELOCATION}}' in text:
            if relocation_yes:
                text = text.replace('{{IF_RELOCATION}}','').replace('{{END_IF_RELOCATION}}','')
            else:
                remove_paragraph(p)
                return
        else:
            # Handle multi-paragraph block (simple state not expected in this template)
            # Markers are unexpected here; leave as-is
            pass
    # Replace placeholders
    for key, val in mapping.items():
        if key in text:
            text = text.replace(key, val)
    if text != p.text:
        # Replace runs with single run to ensure placeholders replaced even if split
        for r in p.runs:
            r.text = ''
        if p.runs:
            p.runs[0].text = text
        else:
            p.add_run(text)

# Process body paragraphs
for p in list(doc.paragraphs):
    process_paragraph(p)

# Process tables
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for p in list(cell.paragraphs):
                process_paragraph(p)

# Save

doc.save(OUT_PATH)
print('Saved', OUT_PATH)
